    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    for row in out:
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] != bg and row[c + 1] == row[c - 1]:
                row[c] = (row[c - 1] + 1) % 10
    return out

